<div class="sda-container"><!-- Cabecera --><header class="sda-header">
<div class="sda-badge">📍 Situación de Aprendizaje</div>
<h1>Cocinando números</h1>
<h2>"Food Truck"</h2>
</header><main class="sda-content"><!-- 1. Identificación -->
<section class="sda-section">
<div class="section-title">
<div class="section-icon">🪪</div>
<h2>1. Identificación</h2>
</div>
