<button id="acceptBtn" class="bg-food-red hover:bg-red-600 text-white font-bold py-4 px-8 rounded-full shadow-lg transform transition hover:scale-105 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 flex items-center gap-3 mx-auto text-lg" disabled="disabled"> <i class="fa-solid fa-lock" id="btnIcon"></i> <span id="btnText">Completa los 4 pasos primero</span> </button></div>
<!-- Mensaje de éxito oculto inicialmente -->
<div id="successMessage" class="hidden mt-8 bg-green-100 border-2 border-green-500 text-green-800 p-6 rounded-2xl text-center transform transition-all scale-95 opacity-0">
<h3 class="text-2xl font-bold mb-2"><i class="fa-solid fa-rocket animate-pulse mr-2"></i> ¡Reto Aceptado!</h3>
<p>Abre Canva, crea tu cuenta o inicia sesión, y empieza a diseñar el logo de tu Food Truck. ¡A por todas, Chef!</p>
</div>
</main></div>
<!-- Script para la interactividad -->
<p>
<script>
        document.addEventListener('DOMContentLoaded', () => {
            const items = document.querySelectorAll('.check-item');
            const progressBar = document.getElementById('progressBar');
            const acceptBtn = document.getElementById('acceptBtn');
            const btnIcon = document.getElementById('btnIcon');
            const btnText = document.getElementById('btnText');
            const successMessage = document.getElementById('successMessage');

            let completedCount = 0;
            const totalItems = items.length;

            items.forEach(item => {
                item.addEventListener('click', function() {
                    // Si ya está completado, no hacer nada
                    if (this.classList.contains('completed')) return;

                    // Marcar como completado
                    this.classList.add('completed');
                    this.classList.replace('border-gray-100', 'border-green-200');
                    this.classList.replace('hover:border-food-yellow', 'hover:border-green-300');

                    completedCount++;

                    // Actualizar barra de progreso
                    const progressPercentage = (completedCount / totalItems) * 100;
                    progressBar.style.width = `${progressPercentage}%`;

                    // Si todos están completados, habilitar el botón
                    if (completedCount === totalItems) {
                        acceptBtn.removeAttribute('disabled');
                        acceptBtn.classList.replace('bg-food-red', 'bg-food-yellow');
                        acceptBtn.classList.replace('hover:bg-red-600', 'hover:bg-yellow-500');
                        acceptBtn.classList.replace('text-white', 'text-food-navy');
                        btnIcon.classList.replace('fa-lock', 'fa-fire-burner');
                        btnText.textContent = "¡Aceptar el Reto y Empezar!";
                    }
                });
            });

            // Acción del botón final
            acceptBtn.addEventListener('click', () => {
                successMessage.classList.remove('hidden');
                // Pequeño timeout para permitir que el display:block se aplique antes de animar
                setTimeout(() => {
                    successMessage.classList.remove('scale-95', 'opacity-0');
                    successMessage.classList.add('scale-100', 'opacity-100');
                }, 50);

                // Ocultar el botón principal para limpiar la vista
                acceptBtn.parentElement.classList.add('hidden');
            });
        });
    </script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

