            --nivel2-border: #F97316;

            --nivel1-bg: #FEE2E2; /* Rojo muy claro */
            --nivel1-border: #EF4444;
        }

        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { font-family: 'Nunito', sans-serif; background-color: var(--bg-color); color: var(--text-main); line-height: 1.5; padding: 20px; }

        .container { max-width: 1200px; margin: 0 auto; background: white; padding: 40px; border-radius: 24px; box-shadow: 0 10px 25px rgba(0,0,0,0.05); }

        /* Header */
        header { text-align: center; margin-bottom: 40px; }
        h1 { font-size: 2.2rem; color: var(--text-main); margin-bottom: 10px; font-weight: 800; }
        .subtitle { font-size: 1.2rem; color: var(--text-muted); margin-bottom: 20px; display: flex; align-items: center; justify-content: center; gap: 10px; }

        .student-info { display: flex; justify-content: center; gap: 30px; margin-bottom: 30px; flex-wrap: wrap; }
        .input-group { display: flex; flex-direction: column; align-items: flex-start; }
        .input-group label { font-weight: 700; font-size: 0.9rem; color: var(--text-muted); margin-bottom: 5px; }
        .input-group input { padding: 10px 15px; border: 2px solid #E2E8F0; border-radius: 10px; font-family: inherit; font-size: 1rem; width: 250px; outline: none; transition: border-color 0.3s;}
        .input-group input:focus { border-color: var(--primary); }

        /* Tabla Rúbrica */
        .rubric-table { width: 100%; border-collapse: separate; border-spacing: 0; border: 2px solid #E2E8F0; border-radius: 16px; overflow: hidden; }

        th, td { padding: 20px 15px; text-align: left; vertical-align: top; border-bottom: 1px solid #E2E8F0; border-right: 1px solid #E2E8F0; }
        th:last-child, td:last-child { border-right: none; }
        tr:last-child td { border-bottom: none; }

        /* Cabeceras de columna */
        th { background-color: #F1F5F9; font-weight: 800; font-size: 1.1rem; text-align: center; }
        th.criterion-col { width: 20%; text-align: left; background-color: white; color: var(--primary); }

        /* Estilos de cabeceras de nivel */
        .level-header { display: flex; flex-direction: column; align-items: center; gap: 5px; }
        .level-header i { font-size: 1.5rem; margin-bottom: 5px; }
        .level-4 th { border-top: 4px solid var(--nivel4-border); color: #047857; }
        .level-3 th { border-top: 4px solid var(--nivel3-border); color: #B45309; }
        .level-2 th { border-top: 4px solid var(--nivel2-border); color: #C2410C; }
        .level-1 th { border-top: 4px solid var(--nivel1-border); color: #B91C1C; }

        /* Celdas de Criterio */
        .criterion-title { font-weight: 800; font-size: 1.1rem; margin-bottom: 5px; display: flex; align-items: center; gap: 8px; }
        .criterion-desc { font-size: 0.85rem; color: var(--text-muted); }

        /* Celdas interactivas (descriptores) */
        .descriptor-cell { cursor: pointer; transition: all 0.2s ease; border-radius: 8px; margin: 2px; }
        .descriptor-cell:hover { transform: translateY(-2px); box-shadow: 0 4px 6px rgba(0,0,0,0.05); }

        /* Estados seleccionados */
        .selected-4 { background-color: var(--nivel4-bg) !important; border: 2px solid var(--nivel4-border) !important; color: #064E3B; font-weight: 600; }
        .selected-3 { background-color: var(--nivel3-bg) !important; border: 2px solid var(--nivel3-border) !important; color: #78350F; font-weight: 600; }
        .selected-2 { background-color: var(--nivel2-bg) !important; border: 2px solid var(--nivel2-border) !important; color: #7C2D12; font-weight: 600; }
        .selected-1 { background-color: var(--nivel1-bg) !important; border: 2px solid var(--nivel1-border) !important; color: #7F1D1D; font-weight: 600; }

        /* Contenido del descriptor */
        .desc-content { font-size: 0.95rem; }

        /* Botones */
        .actions { text-align: center; margin-top: 30px; }
        .btn { background: var(--text-muted); color: white; border: none; padding: 12px 24px; border-radius: 12px; font-size: 1rem; font-weight: bold; cursor: pointer; transition: background 0.3s; font-family: inherit; display: inline-flex; align-items: center; gap: 8px; box-shadow: 0 4px 6px rgba(100, 116, 139, 0.3); }
        .btn:hover { background: #475569; }
