<script>
    // Función para manejar la selección de celdas
    function selectCell(clickedCell, rowId, level) {
        // Encontrar la fila correspondiente
        const row = document.querySelector(`tr[data-row="${rowId}"]`);

        // Quitar las clases de selección de todas las celdas descriptivas de esa fila
        const cells = row.querySelectorAll('.descriptor-cell');
        cells.forEach(cell => {
            cell.classList.remove('selected-4', 'selected-3', 'selected-2', 'selected-1');
            cell.style.border = 'none'; // resetear borde en linea si lo hubiera
        });

        // Añadir la clase correspondiente al nivel seleccionado
        clickedCell.classList.add(`selected-${level}`);
    }

    // Función para borrar toda la selección
    function resetRubric() {
        // Limpiar inputs
        document.getElementById('nombre').value = '';
        document.getElementById('fecha').value = '';

        // Limpiar celdas
        const cells = document.querySelectorAll('.descriptor-cell');
        cells.forEach(cell => {
            cell.classList.remove('selected-4', 'selected-3', 'selected-2', 'selected-1');
        });
    }
</script>
