<p>
<script>
    // Generación de la Diana interactiva con SVG
    const svg = document.getElementById('dianaSvg');
    const cx = 200, cy = 200;
    const radii = [40, 90, 140, 190]; // 4 niveles

    // Colores base para cada cuadrante (cuando se seleccionan)
    // Q1: Arriba (Tareas/Math), Q2: Derecha (TIC), Q3: Abajo (Equipo), Q4: Izquierda (Emociones)
    const quadrantColors = [
        ['#DBEAFE', '#93C5FD', '#60A5FA', '#3B82F6'], // Azules
        ['#EDE9FE', '#C4B5FD', '#A78BFA', '#8B5CF6'], // Morados
        ['#FEF3C7', '#FDE047', '#FACC15', '#EAB308'], // Amarillos/Naranjas
        ['#D1FAE5', '#6EE7B7', '#34D399', '#10B981']  // Verdes
    ];

    // Función para calcular coordenadas polares
    function polarToCartesian(centerX, centerY, radius, angleInDegrees) {
      const angleInRadians = (angleInDegrees - 90) * Math.PI / 180.0;
      return {
        x: centerX + (radius * Math.cos(angleInRadians)),
        y: centerY + (radius * Math.sin(angleInRadians))
      };
    }

    // Función para dibujar un arco (gajo de la diana)
    function describeArc(x, y, innerRadius, outerRadius, startAngle, endAngle){
        const start = polarToCartesian(x, y, outerRadius, endAngle);
        const end = polarToCartesian(x, y, outerRadius, startAngle);
        const startInner = polarToCartesian(x, y, innerRadius, endAngle);
        const endInner = polarToCartesian(x, y, innerRadius, startAngle);
        const largeArcFlag = endAngle - startAngle <= 180 ? "0" : "1";

        return [
            "M", start.x, start.y,
            "A", outerRadius, outerRadius, 0, largeArcFlag, 0, end.x, end.y,
            "L", endInner.x, endInner.y,
            "A", innerRadius, innerRadius, 0, largeArcFlag, 1, startInner.x, startInner.y,
            "Z"
        ].join(" ");
    }

    // Cuadrantes girados 45 grados para hacer una "X" (para que los ejes cardinales queden en el medio de las porciones)
    const quadrants = [
        { start: -45, end: 45, id: 0 },   // Arriba
        { start: 45, end: 135, id: 1 },   // Derecha
        { start: 135, end: 225, id: 2 },  // Abajo
        { start: 225, end: 315, id: 3 }   // Izquierda
    ];

    // Estado para guardar el nivel seleccionado en cada cuadrante (0 = nada)
    let selectedLevels = { 0: 0, 1: 0, 2: 0, 3: 0 };
    const allPaths = [];

    // Generar SVG
    quadrants.forEach((q) => {
        // Generar desde fuera hacia adentro por superposición/click
        radii.forEach((r, levelIndex) => {
            const innerR = levelIndex === 0 ? 0 : radii[levelIndex - 1];
            const outerR = r;
            const path = document.createElementNS("http://www.w3.org/2000/svg", "path");

            path.setAttribute("d", describeArc(cx, cy, innerR, outerR, q.start, q.end));
            path.setAttribute("class", "wedge");
            path.setAttribute("data-quadrant", q.id);
            path.setAttribute("data-level", levelIndex + 1);

            path.addEventListener('click', () => handleWedgeClick(q.id, levelIndex + 1));

            svg.appendChild(path);
            allPaths.push(path);
        });
    });

    // Dibujar líneas divisorias (la "X")
    quadrants.forEach(q => {
        const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
        const pos = polarToCartesian(cx, cy, radii[3], q.end);
        line.setAttribute("x1", cx);
        line.setAttribute("y1", cy);
        line.setAttribute("x2", pos.x);
        line.setAttribute("y2", pos.y);
        line.setAttribute("stroke", "#94A3B8");
        line.setAttribute("stroke-width", "3");
        svg.appendChild(line);
    });

    // Lógica al hacer clic: Rellena hasta el nivel clicado
    function handleWedgeClick(quadrantId, level) {
        selectedLevels[quadrantId] = level;
        updateColors();
    }

    function updateColors() {
        allPaths.forEach(path => {
            const qId = parseInt(path.getAttribute("data-quadrant"));
            const lId = parseInt(path.getAttribute("data-level"));

            // Si el nivel de esta porción es menor o igual al nivel seleccionado para este cuadrante, coloréalo
            if (lId <= selectedLevels[qId]) {
                // Seleccionar color según el nivel (más intense cuanto mayor es el nivel)
                path.style.fill = quadrantColors[qId][lId - 1];
            } else {
                path.style.fill = "white"; // Vacío
            }
        });
    }

    // Función para reiniciar
    function resetDiana() {
        selectedLevels = { 0: 0, 1: 0, 2: 0, 3: 0 };
        document.getElementById('nombre').value = '';
        document.getElementById('fecha').value = '';
        updateColors();
    }
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
